<template><div class="toolbar"><select v-model="node" aria-label="选择主机"><option v-for="n in nodes" :key="n.id" :value="n.id">{{n.name}}</option></select></div><div class="tabs"><button :class="{active:tab==='images'}" @click="tab='images'">本地镜像</button><button :class="{active:tab==='packages'}" @click="tab='packages';loadCatalog()">可信应用发行库</button><button v-if="admin" :class="{active:tab==='import'}" @click="tab='import'">离线导入</button></div><PanelCard v-if="tagging" title="创建镜像版本标签"><ImageTagForm :node="node" :image="tagging" @close="tagging=null"/></PanelCard><PanelCard v-if="tab==='images'" title="本地镜像与版本"><p v-if="error" class="notice danger" role="alert">{{error}}</p><DataTable :rows="images" :columns="columns" row-key="Id"><template #name="{row}"><strong>{{row.RepoTags?.join(', ')||'无标签镜像'}}</strong><small><code>{{row.Id}}</code></small></template><template #Size="{row}">{{bytes(row.Size)}}</template><template #Created="{row}">{{dateTime(row.Created)}}</template><template #actions="{row}"><button v-if="admin" @click="tagging=row">创建版本标签</button><button v-if="admin" class="danger-button" @click="remove(row)">删除未引用镜像</button></template></DataTable></PanelCard><PanelCard v-else-if="tab==='packages'" title="已验证应用发行包"><ResourceState :error="error" @retry="loadCatalog"/><DataTable :rows="catalog" :columns="packageColumns" row-key="digest"><template #digest="{row}"><code>{{row.digest.slice(0,18)}}…</code></template><template #action><RouterLink v-if="admin" to="/deploy">部署此版本</RouterLink></template></DataTable></PanelCard><template v-else-if="tab==='import'"><PanelCard title="导入签名应用发行包" description="用于 Runtime OS 多组件部署，包含镜像、资产与签名。"><PackageUpload :node="node" @verified="loadCatalog"/></PanelCard><PanelCard title="导入独立镜像 TAR" description="单文件上限 256 MiB；大型 Runtime OS 镜像请使用上面的分片应用包导入。"><form @submit.prevent="importImage"><div class="form-grid"><label>镜像 TAR 文件<input type="file" accept=".tar" @change="file=$event.target.files[0]" required></label><label>SHA-256<input v-model="digest" pattern="[a-f0-9]{64}" required></label></div><label><input v-model="confirmed" type="checkbox" required> 我确认将此文件中的镜像加载到所选 Docker 主机</label><p v-if="error" class="notice danger" role="alert">{{error}}</p><p v-if="message" class="notice success">{{message}}</p><button class="primary" :disabled="busy">{{busy?'校验与导入中…':'校验并导入'}}</button></form></PanelCard></template></template>
<script setup>
import ImageTagForm from '../../components/images/ImageTagForm.vue';import {ref,computed,watch} from 'vue';import {useCluster} from '../../stores/cluster';import {useSession} from '../../stores/session';import {infrastructureApi} from '../../api/infrastructure';import {deploymentsApi} from '../../api/deployments';import {useOperations} from '../../composables/useOperations';import {bytes,dateTime} from '../../utils/format';import PanelCard from '../../components/ui/PanelCard.vue';import DataTable from '../../components/ui/DataTable.vue';import ResourceState from '../../components/ui/ResourceState.vue';import PackageUpload from '../../components/deployments/PackageUpload.vue';
const cluster=useCluster(),{nodes,inventory}=cluster,{admin}=useSession(),{preview}=useOperations(),node=ref(nodes.value[0]?.id||''),tab=ref('images'),tagging=ref(null),error=ref(''),catalog=ref([]),file=ref(null),digest=ref(''),confirmed=ref(false),busy=ref(false),message=ref('');watch(nodes,value=>{if(!node.value)node.value=value[0]?.id||'';});watch(node,()=>{if(tab.value==='packages')loadCatalog();});
const images=computed(()=>inventory.value.find(n=>n.id===Number(node.value))?.data?.images||[]),columns=[{key:'name',label:'镜像版本 / 不可变 ID'},{key:'Size',label:'大小'},{key:'Created',label:'创建时间'},{key:'actions',label:'操作'}],packageColumns=[{key:'name',label:'应用'},{key:'version',label:'版本'},{key:'platform',label:'平台'},{key:'components',label:'组件数'},{key:'keyId',label:'签名方'},{key:'digest',label:'包校验和'},{key:'action',label:'操作'}];
async function loadCatalog(){if(!node.value)return;try{catalog.value=await deploymentsApi.catalog(node.value);error.value='';}catch(e){error.value=e.message;}}
async function remove(image){try{await preview(node.value,{action:'image.delete',id:image.Id});}catch(e){error.value=e.message;}}
async function importImage(){busy.value=true;error.value='';try{if(file.value.size>256*1024**2)throw Error('文件超过 256 MiB，请改用签名应用包分片导入。');await infrastructureApi.importImage(node.value,file.value,digest.value);message.value='镜像校验及导入成功。';await cluster.refresh();}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
